import { names } from '../data';

function Table() {
    return (
        <table id='table'>
            <thead>
                <tr>
                    <th>Name</th>
                </tr>
                <tr>
                    {names.map((name, key) =>
                        <th id={key}>
                            {name}
                        </th>)
                    }
                </tr>
            </thead>
            <tbody>
                <tr>
                    <input type="number" defaultValue="0" />
                </tr>
            </tbody>
        </table>
    );
}

export default Table;
